# Explicit small-business cash and legal household links; no PD transfer.
build_retail_sme_features<-function(business_cashflows,owner_drawings,household_obligations,liability_links,coverage,business_id,owner_customer_ids,business_debt_facility_ids,household_debt_service_window,as_of,information_cutoff,lookback_days,currency,context=NULL){times<-.cr_rb_window(as_of,information_cutoff,lookback_days,context);anchor<-times$anchor;cutoff<-times$cutoff;ctx<-times$context;days<-times$days;start<-times$start;.cr_rf_text(business_id,'business_id');owners<-.cr_rf_strings(owner_customer_ids,'owner_customer_ids',FALSE);debt_ids<-.cr_rf_strings(business_debt_facility_ids,'business_debt_facility_ids');.cr_rf_text(currency,'currency');complete<-.cr_rb_coverage(coverage,cutoff,start,anchor);if(!is.null(ctx$currency)&&ctx$currency!=currency) .cr_error('TARGET_MISMATCH','Context currency differs from business currency');envelope<-if(inherits(household_obligations,'CalcResult'))unclass(household_obligations)else household_obligations;if(!.cr_object(envelope)||!identical(envelope$method_id,'retail_features.aggregate_household_obligations')||!.cr_object(envelope$value)||!.cr_object(envelope$context)) .cr_error('RETAIL_ARTIFACT','Supply household aggregation result with dated context');household<-envelope$value;hctx<-envelope$context;window<-household_debt_service_window;if(!.cr_object(window)||!identical(window$from,as.character(start+1))||!identical(window$through,as_of)||!identical(window$period,household$period)) .cr_error('TARGET_MISMATCH','Household debt-service period must explicitly cover the same cashflow window');if(!identical(household$currency,currency)||!identical(hctx$as_of,as_of)||!identical(hctx$known_at,information_cutoff)) .cr_error('TARGET_MISMATCH','Household obligations currency and dated context must match');households<-household$households;if(!is.list(households)) .cr_error('RETAIL_ARTIFACT','Household aggregation lacks household rows');selected<-list();seen_owners<-overlap<-character()
 for(row in households){.cr_data_required(row,c('household_id','customer_ids','facility_ids','known_budget_debt_service'));members<-.cr_rf_strings(row$customer_ids,'household.customer_ids');facilities<-.cr_rf_strings(row$facility_ids,'household.facility_ids');matched<-intersect(members,owners);if(!length(matched))next;if(length(intersect(seen_owners,matched))) .cr_error('RETAIL_ENTITY','Owner has multiple economic households in same snapshot');seen_owners<-union(seen_owners,matched);overlap<-union(overlap,intersect(facilities,debt_ids));.cr_rf_number(row$known_budget_debt_service,'known_budget_debt_service',0);if(!('total_budget_debt_service'%in%names(row))) .cr_error('RETAIL_ARTIFACT','Explicit nullable household total required');if(!is.null(row$total_budget_debt_service)) .cr_rf_number(row$total_budget_debt_service,'total_budget_debt_service',0);selected[[length(selected)+1L]]<-list(household_id=row$household_id,owner_customer_ids=as.list(sort(matched)),known_budget_debt_service=row$known_budget_debt_service,total_budget_debt_service=row$total_budget_debt_service,facility_ids=as.list(facilities))};selected<-.cr_rf_sort(selected,'household_id');missing<-sort(setdiff(owners,seen_owners));household_complete<-!length(missing)&&all(vapply(selected,function(r)!is.null(r$total_budget_debt_service),logical(1)));household_service<-.cr_loss_sum(vapply(selected,`[[`,numeric(1),'known_budget_debt_service'));flow_release<-.cr_rf_releases(business_cashflows,'transaction_id',cutoff,'business cashflows');visible<-list();flows<-list();allowed<-sort(c('SALES','OPERATING_COST','TAX','CAPEX','DEBT_SERVICE','FINANCING','OWNER_DRAW','OWNER_CONTRIBUTION'))
 for(row in flow_release$rows){.cr_data_required(row,c('business_id','posted_at','amount','category','currency'));posted<-.cr_data_date(row$posted_at,'posted_at');.cr_rf_number(row$amount,'amount');if(row$business_id!=business_id||row$currency!=currency) .cr_error('RETAIL_ENTITY','Business flows must match business identity and currency');if(posted>.cr_data_date(row$known_at,'known_at')) .cr_error('RETAIL_DATE','Business posting cannot follow receipt');if(!(row$category%in%allowed)) .cr_error('RETAIL_CASHFLOW','Explicit supported business category required');if(row$category=='SALES') .cr_rf_text(row$counterparty_id,'sales counterparty_id');if(row$category=='DEBT_SERVICE'&&(is.null(row$facility_id)||!(row$facility_id%in%debt_ids))) .cr_error('RETAIL_ENTITY','Debt service must identify a declared business debt facility');if((row$category=='OWNER_DRAW'&&row$amount>0)||(row$category=='OWNER_CONTRIBUTION'&&row$amount<0)) .cr_error('RETAIL_TRANSFER','Owner draws are business debits; contributions are credits');if(posted<=anchor)visible[[row$transaction_id]]<-row;if(start<posted&&posted<=anchor)flows[[length(flows)+1L]]<-row}
 draw_release<-.cr_rf_releases(owner_drawings,'drawing_id',cutoff,'owner drawings');matched_business<-matched_household<-character();draw_rows<-list();for(row in draw_release$rows){.cr_data_required(row,c('business_transaction_id','household_transaction_id','owner_customer_id','business_posted_at','household_posted_at','business_amount','household_amount','currency'));original<-visible[[row$business_transaction_id]];bdate<-.cr_data_date(row$business_posted_at,'business_posted_at');hdate<-.cr_data_date(row$household_posted_at,'household_posted_at');known<-.cr_data_date(row$known_at,'known_at');ba<-.cr_rf_number(row$business_amount,'business_amount');ha<-.cr_rf_number(row$household_amount,'household_amount',0);.cr_rf_text(row$household_transaction_id,'household_transaction_id');if(is.null(original)||original$category!='OWNER_DRAW'||!(row$owner_customer_id%in%owners)||row$currency!=currency||ba!= -ha||ba!=original$amount||row$business_posted_at!=original$posted_at) .cr_error('RETAIL_TRANSFER','Owner drawing must match opposite business and household transfer legs exactly');if(max(bdate,hdate)>known||hdate>anchor) .cr_error('RETAIL_DATE','Owner transfer evidence cannot anticipate household receipt');if(row$business_transaction_id%in%matched_business||row$household_transaction_id%in%matched_household) .cr_error('DOUBLE_COUNTING','One owner-draw transfer cannot be assigned twice');matched_business<-c(matched_business,row$business_transaction_id);matched_household<-c(matched_household,row$household_transaction_id);if((start<bdate&&bdate<=anchor)||(start<hdate&&hdate<=anchor))draw_rows[[length(draw_rows)+1L]]<-list(drawing_id=row$drawing_id,owner_customer_id=row$owner_customer_id,business_transaction_id=row$business_transaction_id,household_transaction_id=row$household_transaction_id,business_posted_at=row$business_posted_at,household_posted_at=row$household_posted_at,business_amount=ba,household_amount=ha)}
 unmatched<-sort(vapply(Filter(function(r)r$category=='OWNER_DRAW'&&!(r$transaction_id%in%matched_business),flows),`[[`,character(1),'transaction_id'));totals<-setNames(lapply(allowed,function(k).cr_loss_sum(vapply(Filter(function(r)r$category==k,flows),`[[`,numeric(1),'amount'))),allowed);operating<-.cr_loss_sum(unlist(totals[c('SALES','OPERATING_COST','TAX')],use.names=FALSE));before_debt<-.cr_loss_sum(c(operating,totals$CAPEX));after_debt<-.cr_loss_sum(c(before_debt,totals$DEBT_SERVICE));customers<-list();months<-list();for(offset in seq_len(days)){month<-substr(as.character(start+offset),1,7);if(is.null(months[[month]]))months[[month]]<-numeric()};for(row in flows)if(row$category=='SALES'){customers[[row$counterparty_id]]<-c(customers[[row$counterparty_id]],row$amount);month<-substr(row$posted_at,1,7);months[[month]]<-c(months[[month]],row$amount)};customer_sales<-if(length(customers))setNames(lapply(sort(names(customers)),function(k).cr_loss_sum(customers[[k]])),sort(names(customers)))else .cr_empty_object();monthly_sales<-setNames(lapply(sort(names(months)),function(k).cr_loss_sum(months[[k]])),sort(names(months)));sales<-totals$SALES;hhi<-if(sales<=0||any(unlist(customer_sales)<0))NULL else .cr_loss_sum((unlist(customer_sales)/sales)^2);peak<-if(sales<=0||any(unlist(monthly_sales)<0))NULL else max(unlist(monthly_sales))/sales
 liability_release<-.cr_rf_releases(liability_links,'liability_id',cutoff,'owner liabilities');liabilities<-list();for(row in liability_release$rows){.cr_data_required(row,c('business_id','customer_id','liability_type','effective_from','evidence_reference'));if(!all(c('effective_until','liability_fraction','maximum_amount')%in%names(row))) .cr_error('RETAIL_CONTRACT','Liability end, fraction and cap require explicit nullable values');first<-.cr_data_date(row$effective_from,'effective_from');last<-if(is.null(row$effective_until))NULL else .cr_data_date(row$effective_until,'effective_until');if(!is.null(last)&&last<=first) .cr_error('RETAIL_DATE','Liability interval must be nonempty');if(row$business_id!=business_id||!(row$customer_id%in%owners)) .cr_error('RETAIL_ENTITY','Legal links must match business and supplied owners');if(!(row$liability_type%in%c('LIMITED_OWNERSHIP','PERSONAL_GUARANTEE','UNLIMITED_LIABILITY'))) .cr_error('RETAIL_LIABILITY','Declare legal liability type; ownership is not a guarantee');.cr_rf_text(row$evidence_reference,'evidence_reference');if(!is.null(row$liability_fraction)){v<-.cr_rf_number(row$liability_fraction,'liability_fraction');if(v<0||v>1) .cr_error('RETAIL_LIABILITY','Liability fraction must be in [0,1]')};if(!is.null(row$maximum_amount)) .cr_rf_number(row$maximum_amount,'maximum_amount',0);if(first<=anchor&&(is.null(last)||anchor<last))liabilities[[length(liabilities)+1L]]<-row};combined<-if(!complete||!household_complete||length(overlap))NULL else .cr_loss_sum(c(after_debt,-household_service));household_draw<-.cr_loss_sum(vapply(Filter(function(r)start<.cr_data_date(r$household_posted_at,'household_posted_at')&&.cr_data_date(r$household_posted_at,'household_posted_at')<=anchor,draw_rows),`[[`,numeric(1),'household_amount'))
 .cr_result(list(business_id=business_id,owner_customer_ids=as.list(sort(owners)),as_of=as_of,information_cutoff=information_cutoff,currency=currency,lookback_days=days,coverage_complete=complete,business_category_net=totals,known_operating_cash_before_capex_and_debt=operating,known_cash_before_business_debt=before_debt,known_cash_after_business_debt=after_debt,cash_after_business_debt=if(complete)after_debt else NULL,owner_draw_business_outflows= -totals$OWNER_DRAW,matched_owner_draw_household_inflows=household_draw,owner_transfers=.cr_rf_sort(draw_rows,'drawing_id'),unmatched_business_drawing_ids=as.list(unmatched),customer_sales=customer_sales,customer_sales_hhi=hhi,monthly_sales=monthly_sales,observed_peak_month_sales_share=peak,owner_households=selected,missing_owner_household_ids=as.list(missing),known_household_budget_debt_service=household_service,total_household_budget_debt_service=if(household_complete)household_service else NULL,overlapping_business_household_facility_ids=as.list(sort(overlap)),cash_after_business_and_household_debt=combined,legal_liability_links=liabilities),'retail_features.build_retail_sme_features',currency,ctx,diagnostics=list(coverage=coverage,household_result_fingerprint=.cr_hash(envelope),household_debt_service_window=window,excluded_cashflow_releases=flow_release$excluded,excluded_drawing_releases=draw_release$excluded,excluded_liability_releases=liability_release$excluded),limitations=list('Business sales are not household income. Operating cash excludes financing, owner drawings and owner contributions; matched drawings are transfers, never a second source of consolidated cash. Cash after household debt excludes household living costs and therefore is not an affordability or distributable-income measure. Shared business/household debt facility IDs suppress combined subtraction to avoid double counting. Monthly sales and customer concentration describe supplied observations, not an estimated seasonal forecast. Legal ownership, guarantees and unlimited liability remain explicit; no owner or business PD is copied.'))}
